def header(row,english=False):
    if english:
        return '**Scope and grading.** All teaching companies, quantities, programme outcomes and calculation assumptions are fictional; explicitly dated official statements and supplied definitions are separate. Work through both independent applications, each with three tasks. Total24 points, pass15. Reasoned partial performance and alternative supported judgments count anywhere appropriate. There is no minimum per task, perfection demand, required wording or extra-task quota. Each following essential performance is assessed separately: '+ '; '.join(row['essentialEn'])+'. If any one is entirely absent throughout the whole submission or consistently substantively incorrect, cap the total at14. Meaningful imperfect performance anywhere counts; isolated mistakes or omitted details do not trigger this limit. A wholly omitted second application also caps at14 under the unchanged two-application contract; an omitted subtask is different. Credit the same performance once. Source reading:10 October2026; source-specific dates and remaining unknowns govern actual-event statements.'
    return '**Rahmen und Bewertung.** Unterrichtsfirmen, Mengen, Programmergebnisse und Rechenannahmen sind fiktiv; ausdrücklich datierte amtliche Aussagen und gelieferte Definitionen sind getrennt. Bearbeite beide unabhängigen Anwendungen mit je drei Aufträgen.24 Punkte, bestanden ab15. Nachvollziehbare Teilleistungen und andere begründete Urteile zählen an jeder passenden Stelle. Keine Mindestpunkte je Auftrag, Fehlerfreiheitsforderung, vorgeschriebene Formulierung oder weitere Aufgabenquote. Folgende wesentliche Leistungen werden jeweils getrennt geprüft: '+ '; '.join(row['essentialDe'])+'. Fehlt eine davon in der gesamten Arbeit vollständig oder wird sie durchgehend sachlich falsch ausgeführt, ist der Gesamtwert auf14 begrenzt. Erkennbare, auch unvollkommene Leistung an beliebiger Stelle zählt; einzelne Fehler und fehlende Details lösen die Grenze nicht aus. Eine ganz ausgelassene zweite Anwendung begrenzt nach dem unveränderten Zwei-Anwendungs-Vertrag ebenfalls auf14; ein ausgelassener Teilauftrag ist etwas anderes. Dieselbe Leistung wird nur einmal bepunktet. Quellenlektüre:10.10.2026; für reale Aussagen gelten die jeweils genannten Quelldaten und offen gebliebenen Stände.'

def task(row,en=False):
    parts=[header(row,en)]
    for label,c in zip('AB',row['cases']):
        parts += [('**Case '+label+'**' if en else '**Fall '+label+'**'),c['materialEn' if en else 'materialDe']]
        parts += [str(n)+'. '+q for n,q in enumerate(c['questionsEn' if en else 'questionsDe'],1)]
    if row['sources']:
        parts += ['**Official source anchors, selected readings.**' if en else '**Amtliche Quellenanker, gezielte Lektüre.**']
        parts += ['['+label+']('+url+')' for label,url in row['sources']]
    return '\n\n'.join(parts)
def solution(row,en=False):
    parts=['Use the whole rubric and separate essential rules; the following are defensible routes, not mandatory wording.' if en else 'Nutze das ganze Raster und die getrennten Kernregeln; folgende Lösungen zeigen mögliche Wege, keine Pflichtformulierung.']
    for label,c in zip('AB',row['cases']):
        parts += ['**Case '+label+'**' if en else '**Fall '+label+'**']
        parts += [str(n)+'. '+s for n,s in enumerate(c['solutionsEn' if en else 'solutionsDe'],1)]
    return '\n\n'.join(parts)
